const std = @import("std");

pub fn main() !void {
    const s1 = "kitten";
    const s2 = "sitting";
    const m = s1.len;
    const n = s2.len;
    var dp: [7][8]u32 = [_][8]u32{[_]u32{0} ** 8} ** 7;

    for (0..m + 1) |i| dp[i][0] = @intCast(i);
    for (0..n + 1) |j| dp[0][j] = @intCast(j);

    for (1..m + 1) |i| {
        for (1..n + 1) |j| {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + @min(@min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]);
            }
        }
    }

    std.debug.print("Edit distance: {}\n", .{dp[m][n]});
}

